35	const codexDefaultProvidersByCacheKey = new Map<
36	  string,
37	  Pick<
38	    DefaultProviders,
39	    | 'gradingJsonProvider'
40	    | 'gradingProvider'
41	    | 'llmRubricProvider'
42	    | 'suggestionsProvider'
43	    | 'synthesizeProvider'
44	    | 'webSearchProvider'
45	  >
46	>();
47	
48	const codexSdkAvailabilityByBaseDir = new Map<string, boolean>();
49	
50	function getCodexEnvString(env: EnvOverrides | undefined, key: string): string | undefined {
51	  return env?.[key] || getEnvString(key);
52	}
53	
54	function getCodexHome(env?: EnvOverrides): string {
55	  const homeDir = os.homedir?.();
56	  const defaultHome =
57	    typeof homeDir === 'string' && homeDir ? path.join(homeDir, '.codex') : undefined;
58	  const codexHome = getCodexEnvString(env, 'CODEX_HOME') || defaultHome || '.codex';
59	  return path.resolve(codexHome);
60	}
61	
62	function getTempDirectory(): string {
63	  const tempDir = os.tmpdir?.();
64	  return typeof tempDir === 'string' && tempDir ? tempDir : process.cwd();
65	}
66	
67	function getCodexDefaultWorkingDir(): string {
68	  if (!codexDefaultWorkingDir) {
69	    codexDefaultWorkingDir = fs.mkdtempSync(
70	      path.join(getTempDirectory(), 'promptfoo-codex-default-'),
71	    );
72	  }
73	
74	  return codexDefaultWorkingDir;
75	}
76	
77	function hasCodexAuthFile(env?: EnvOverrides): boolean {
78	  try {
79	    const stats = fs.statSync(path.join(getCodexHome(env), CODEX_AUTH_FILENAME));
80	    return stats.isFile() && stats.size > 0;
81	  } catch {
82	    return false;
83	  }
84	}
85	
86	function hasCodexSdkPackage(baseDir: string): boolean {
87	  const cached = codexSdkAvailabilityByBaseDir.get(baseDir);
88	  if (cached !== undefined) {
89	    return cached;
90	  }
91	
92	  const hasPackage = resolvePackageEntryPoint(CODEX_SDK_PACKAGE_NAME, baseDir) !== null;
93	  codexSdkAvailabilityByBaseDir.set(baseDir, hasPackage);
94	  return hasPackage;
95	}
96	
97	function canLoadCodexSdkPackage(): boolean {
98	  return [process.cwd(), getDirectory()].some((baseDir) => hasCodexSdkPackage(baseDir));
99	}
100	
101	export function hasCodexDefaultCredentials(env?: EnvOverrides): boolean {
102	  const hasCodexApiKey = Boolean(getCodexEnvString(env, 'CODEX_API_KEY'));
103	  return (hasCodexApiKey || hasCodexAuthFile(env)) && canLoadCodexSdkPackage();
104	}
105	
106	function getCodexDefaultProviderConfig(
107	  env: EnvOverrides | undefined,
108	  config?: OpenAICodexSDKConfig,
109	  defaultWorkingDir: string = getCodexDefaultWorkingDir(),
110	): OpenAICodexSDKConfig {
111	  const codexHome = getCodexEnvString(env, 'CODEX_HOME');
112	  const workingDir = config?.working_dir || defaultWorkingDir;
113	  fs.mkdirSync(workingDir, { recursive: true });
114	  const cliEnv = {
115	    ...(codexHome ? { CODEX_HOME: path.resolve(codexHome) } : {}),
116	    ...config?.cli_env,
117	  };
118	
119	  return {
120	    approval_policy: 'never',
121	    sandbox_mode: 'read-only',
122	    skip_git_repo_check: true,
123	    working_dir: workingDir,
124	    ...config,
125	    ...(Object.keys(cliEnv).length > 0 ? { cli_env: cliEnv } : {}),
126	  };
127	}
128	
129	function getCodexDefaultProvidersCacheKey(env?: EnvOverrides): string {
130	  return JSON.stringify({
131	    CODEX_HOME: getCodexEnvString(env, 'CODEX_HOME'),
132	    hasCodexApiKey: Boolean(getCodexEnvString(env, 'CODEX_API_KEY')),
133	    hasOpenAiApiKey: Boolean(getCodexEnvString(env, 'OPENAI_API_KEY')),
134	  });
135	}
136	
137	export function getCodexDefaultProviders(
138	  env?: EnvOverrides,
139	): Pick<
140	  DefaultProviders,
141	  | 'gradingJsonProvider'
142	  | 'gradingProvider'
143	  | 'llmRubricProvider'
144	  | 'suggestionsProvider'
145	  | 'synthesizeProvider'
146	  | 'webSearchProvider'
147	> {
148	  const cacheKey = getCodexDefaultProvidersCacheKey(env);
149	  const cachedProviders = codexDefaultProvidersByCacheKey.get(cacheKey);
150	  if (cachedProviders) {
151	    return cachedProviders;
152	  }
153	
154	  const defaultWorkingDir = getCodexDefaultWorkingDir();
155	
156	  const gradingProvider = new OpenAICodexSDKProvider({
157	    config: getCodexDefaultProviderConfig(env, undefined, defaultWorkingDir),
158	    env,
159	  });
160	  const gradingJsonProvider = new OpenAICodexSDKProvider({
161	    config: getCodexDefaultProviderConfig(
162	      env,
163	      {
164	        output_schema: CODEX_GRADING_OUTPUT_SCHEMA,
165	      },
166	      defaultWorkingDir,
167	    ),
168	    env,
169	  });
170	  const webSearchProvider = new OpenAICodexSDKProvider({
171	    config: getCodexDefaultProviderConfig(
172	      env,
173	      {
174	        network_access_enabled: true,
175	        output_schema: CODEX_GRADING_OUTPUT_SCHEMA,
176	        web_search_mode: 'live',
177	      },
178	      defaultWorkingDir,
179	    ),
180	    env,
181	  });
182	
183	  const providers = {
184	    gradingJsonProvider,
185	    gradingProvider,
186	    llmRubricProvider: gradingJsonProvider,
187	    suggestionsProvider: gradingProvider,
188	    synthesizeProvider: gradingProvider,
189	    webSearchProvider,
190	  };
191	  codexDefaultProvidersByCacheKey.set(cacheKey, providers);
192	  return providers;
193	}
194	
195	export function clearCodexDefaultProvidersForTesting(): void {
196	  codexDefaultProvidersByCacheKey.clear();
197	  codexSdkAvailabilityByBaseDir.clear();
198	  codexDefaultWorkingDir = undefined;
199	}
