function resolveCodexApiKey(env?: EnvOverrides): string | undefined {
  return (
    env?.OPENAI_API_KEY ||
    env?.CODEX_API_KEY ||
    getEnvString('OPENAI_API_KEY') ||
    getEnvString('CODEX_API_KEY') ||
    undefined
